import{_ as a,a as s,c as t,ac as n}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"Node 服务端口被占用","description":"找到占用端口的进程，核对是否是已有服务实例。","frontmatter":{"title":"Node 服务端口被占用","description":"找到占用端口的进程，核对是否是已有服务实例。","sources":[{"repository":"show-cmd","file":"docs/site/scenarios/node-port-in-use.md"}],"showdocs":{"topics":[{"id":"javascript","title":"JavaScript","link":"/topics/javascript/"},{"id":"engineering","title":"编辑器与 IDE","link":"/topics/engineering/"},{"id":"network","title":"网络配置与诊断","link":"/topics/network/"}],"kind":"排错","scope":"general","audience":"general","group":"语言与开发","summary":"找到占用端口的进程，核对是否是已有服务实例。","status":"active","related":[{"title":"npm 依赖安装失败","link":"/programming/web-base/javascript/plus/troubleshooting/npm-install-fails","kind":"排错","scope":"general","audience":"general"},{"title":"ssh 工具","link":"/systems/network-remote/network/plus/subjects/ssh-%E5%B7%A5%E5%85%B7","kind":"知识专题","scope":"general","audience":"general"},{"title":"Wireshark(过滤表达式)","link":"/systems/network-remote/network/plus/ecosystem/wireshark(%E8%BF%87%E6%BB%A4%E8%A1%A8%E8%BE%BE%E5%BC%8F)","kind":"命令与对象入口","scope":"general","audience":"general"},{"title":"API契约、请求与故障定位","link":"/tools/developer-tools/api-debugging/api-contracts-and-diagnostics","kind":"API调试上手与对象","scope":"general","audience":"general"},{"title":"JavaScript 操作与命令","link":"/programming/web-base/javascript/plus/ecosystem/javascript-general-general","kind":"排错","scope":"general","audience":"general"}],"prev":{"text":"npm 依赖安装失败","link":"/programming/web-base/javascript/plus/troubleshooting/npm-install-fails"},"next":{"text":"JavaScript 事件循环：任务、微任务与渲染机会","link":"/programming/web-base/javascript/base/advanced/event-loop"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"npm 依赖安装失败","link":"/programming/web-base/javascript/plus/troubleshooting/npm-install-fails"},"next":{"text":"JavaScript 事件循环：任务、微任务与渲染机会","link":"/programming/web-base/javascript/base/advanced/event-loop"}},"headers":[],"relativePath":"programming/web-base/javascript/plus/troubleshooting/node-port-in-use.md","filePath":"programming/web-base/javascript/plus/troubleshooting/node-port-in-use.md"}'),r={name:"programming/web-base/javascript/plus/troubleshooting/node-port-in-use.md"};function o(i,e,l,p,d,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="node-服务端口被占用" tabindex="-1">Node 服务端口被占用 <a class="header-anchor" href="#node-服务端口被占用" aria-label="Permalink to &quot;Node 服务端口被占用&quot;">​</a></h1><p>找到占用端口的进程，核对是否是已有服务实例。</p><p>监听成功后，服务持有的是一个地址与端口组合。<code>EADDRINUSE</code> 出现在绑定监听地址时，浏览器刷新或重装 npm 依赖都无法释放该资源。同一个进程中的两个 server 也可能竞争同一端口；先将实际监听地址、进程 ID 和启动日志对应起来。</p><h2 id="排查步骤" tabindex="-1">排查步骤 <a class="header-anchor" href="#排查步骤" aria-label="Permalink to &quot;排查步骤&quot;">​</a></h2><h3 id="_1-记录错误中的地址和端口" tabindex="-1">1. 记录错误中的地址和端口 <a class="header-anchor" href="#_1-记录错误中的地址和端口" aria-label="Permalink to &quot;1. 记录错误中的地址和端口&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>node server.js</span></span></code></pre></div><p><strong>预期结果:</strong> 从 EADDRINUSE 行确认实际端口，例如 3000；核对是否和配置一致。</p><h3 id="_2-按操作系统查找监听进程" tabindex="-1">2. 按操作系统查找监听进程 <a class="header-anchor" href="#_2-按操作系统查找监听进程" aria-label="Permalink to &quot;2. 按操作系统查找监听进程&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>lsof -nP -iTCP:3000 -sTCP:LISTEN</span></span>
<span class="line"><span># Windows: netstat -ano | findstr :3000</span></span></code></pre></div><p><strong>预期结果:</strong> 得到进程 ID，再查看进程名与启动路径，判断是否为旧实例。</p><h3 id="_3-按项目配置选择可用端口" tabindex="-1">3. 按项目配置选择可用端口 <a class="header-anchor" href="#_3-按项目配置选择可用端口" aria-label="Permalink to &quot;3. 按项目配置选择可用端口&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$env:PORT=&quot;3001&quot;; node server.js</span></span>
<span class="line"><span># 上行为PowerShell；Bash使用 PORT=3001 node server.js</span></span></code></pre></div><p><strong>预期结果:</strong> 新实例按 <code>PORT</code> 监听新端口后，再访问该地址并核实收到新实例的响应。修改环境变量只对读取它的代码有效；如实际地址未变，请检查入口的 <code>listen</code> 参数与配置优先级。</p><h2 id="常见报错" tabindex="-1">常见报错 <a class="header-anchor" href="#常见报错" aria-label="Permalink to &quot;常见报错&quot;">​</a></h2><h3 id="eaddrinuse-0-0-0-0-3000" tabindex="-1">EADDRINUSE 0.0.0.0:3000 <a class="header-anchor" href="#eaddrinuse-0-0-0-0-3000" aria-label="Permalink to &quot;EADDRINUSE 0.0.0.0:3000&quot;">​</a></h3><p><strong>原因:</strong> 同端口已有监听者，包括绑定全部接口的进程。</p><p><strong>处理方式:</strong> 确认 PID 和进程身份，再决定复用、正常关闭或换端口。</p><h3 id="换端口后仍报错" tabindex="-1">换端口后仍报错 <a class="header-anchor" href="#换端口后仍报错" aria-label="Permalink to &quot;换端口后仍报错&quot;">​</a></h3><p><strong>原因:</strong> 应用未读取 PORT，或还有另一个监听地址。</p><p><strong>处理方式:</strong> 检查实际 listen 调用、配置优先级和日志中的地址。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/programming/web-base/nodejs/plus/troubleshooting/node">node</a></li><li><a href="/tools/command-tools/cli/reference/lsof">lsof</a></li></ul><h2 id="官方资料" tabindex="-1">官方资料 <a class="header-anchor" href="#官方资料" aria-label="Permalink to &quot;官方资料&quot;">​</a></h2><ul><li><a href="https://nodejs.org/api/errors.html" target="_blank" rel="noopener noreferrer">https://nodejs.org/api/errors.html</a></li><li><a href="https://nodejs.org/api/net.html" target="_blank" rel="noopener noreferrer">https://nodejs.org/api/net.html</a></li></ul>`,24)])])}const u=a(r,[["render",o]]);export{g as __pageData,u as default};
